import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import dynamic from 'next/dynamic';
import GuestTrialBadge from '@/src/components/auth/GuestTrialBadge';
import TrialExpiredGate from '@/src/components/auth/TrialExpiredGate';
import AccountBar from '@/src/components/auth/AccountBar';
import { LAST_SEEN_VERSION_KEY } from '@/src/components/game/ChangelogModal';
import AnnouncementCenter, { SEEN_ANNOUNCEMENTS_KEY, SEEN_REMOTE_ANNOUNCEMENTS_KEY } from '@/src/components/game/AnnouncementCenter';
import VersionBadge from '@/src/components/game/VersionBadge';
import MaintenanceGate from '@/src/components/game/MaintenanceGate';
import NotificationSettings from '@/src/components/settings/NotificationSettings';
import RemoteConfigStatusCard from '@/src/components/settings/RemoteConfigStatusCard';
import ConnectionStatusBanner from '@/src/components/system/ConnectionStatusBanner';
import SaveSyncStatus from '@/src/components/system/SaveSyncStatus';
import ShopCategoryTabs from '@/src/components/shop/ShopCategoryTabs';
import PixelModal from '@/src/components/PixelModal';
import ActionPickerModal from '@/src/components/care/ActionPickerModal';
