import { addInventory, applyStats, clamp, defaultSave, getAnimal, getEvolution, getMood, getTimeOfDay, getUnlockedAchievements, itemById, levelPet, newPet, randomWeather, safeParseSave, todayKey, xpNeed } from '@/lib/gameLogic';
import { careOptionsByAction } from '@/src/data/careOptions';
